import pandas as pd
import requests
from datetime import datetime, timezone

now = datetime.now(timezone.utc)
now_epoch = int(now.timestamp())

API_KEY = CREDENTIALS.get('EIA_API_KEY', '')

EXPECTED_COLUMNS = [
    'series_id', 'description', 'category',
    'unit', 'period', 'latest_value',
    'prior_value', 'change_wow', 'change_wow_pct',
    'value_1y_ago', 'change_yoy', 'change_yoy_pct',
    'percentile_5y', 'regime_flag',
    'investment_thesis', 'etf_ticker', '_epoch',
]

SERIES = [
    {'id': 'WCESTUS1', 'desc': 'US Crude Commercial Stocks (excl. SPR)', 'cat': 'crude_inventory', 'etf': 'USO'},
    {'id': 'WCRSTUS1', 'desc': 'Strategic Petroleum Reserve Stocks', 'cat': 'crude_spr', 'etf': 'USO'},
    {'id': 'W_EPC0_SAX_YCUOK_MBBL', 'desc': 'Cushing OK Crude Stocks (WTI delivery hub)', 'cat': 'crude_cushing', 'etf': 'USO'},
    {'id': 'WGTSTUS1', 'desc': 'US Total Motor Gasoline Stocks', 'cat': 'gasoline_inventory', 'etf': 'UGA'},
    {'id': 'WDISTUS1', 'desc': 'US Distillate Fuel Oil Stocks', 'cat': 'distillate_inventory', 'etf': 'BNO'},
    {'id': 'WPULEUS3', 'desc': 'US Refinery Capacity Utilisation %', 'cat': 'refining', 'etf': 'XLE'},
    {'id': 'WGFUPUS2', 'desc': 'US Finished Motor Gasoline Product Supplied (demand)', 'cat': 'gasoline_demand', 'etf': 'UGA'},
]

def classify_inventory(change_wow_pct):
    if change_wow_pct is None:
        return 'NEUTRAL'
    if change_wow_pct <= -2.0:
        return 'DRAW_HEAVY'
    if change_wow_pct <= -0.5:
        return 'DRAW'
    if change_wow_pct >= 2.0:
        return 'BUILD_HEAVY'
    if change_wow_pct >= 0.5:
        return 'BUILD'
    return 'NEUTRAL'

def classify_refining(latest):
    if latest is None:
        return 'TYPICAL'
    if latest >= 92.0:
        return 'ELEVATED'
    if latest <= 82.0:
        return 'DEPRESSED'
    return 'TYPICAL'

def classify_demand(change_yoy_pct):
    if change_yoy_pct is None:
        return 'TYPICAL'
    if change_yoy_pct >= 3.0:
        return 'STRONG'
    if change_yoy_pct <= -3.0:
        return 'WEAK'
    return 'TYPICAL'

def percentile(values, target):
    if not values:
        return None
    below = 0
    total = 0
    for vi in range(len(values)):
        v = values[vi]
        if v is None:
            continue
        total = total + 1
        if v <= target:
            below = below + 1
    if total == 0:
        return None
    return round(100.0 * below / total, 1)

def thesis_for(category, regime, etf):
    if category == 'crude_inventory':
        if regime == 'DRAW_HEAVY':
            return 'Bullish oil - heavy crude draw signals tight supply; long ' + etf + ', long XLE'
        if regime == 'DRAW':
            return 'Modestly bullish oil - long ' + etf + ' on continued draws'
        if regime == 'BUILD_HEAVY':
            return 'Bearish oil - heavy build signals oversupply; short ' + etf + ' / long DUG'
        if regime == 'BUILD':
            return 'Modestly bearish oil - track for trend continuation before sizing'
        return 'No directional bias from inventories alone'
    if category == 'crude_cushing':
        if regime == 'DRAW_HEAVY':
            return 'WTI delivery hub draining - bullish near-month WTI vs Brent'
        if regime == 'BUILD_HEAVY':
            return 'Cushing filling - pressure on near-month WTI; widen WTI-Brent spread short'
        return 'Cushing stable'
    if category == 'gasoline_inventory':
        if regime == 'DRAW_HEAVY' or regime == 'DRAW':
            return 'Bullish gasoline - long ' + etf + '; refiners benefit (XLE)'
        if regime == 'BUILD_HEAVY' or regime == 'BUILD':
            return 'Bearish gasoline - short ' + etf + '; refiners face crack-spread compression'
        return 'Gasoline range-bound'
    if category == 'distillate_inventory':
        if regime == 'DRAW_HEAVY' or regime == 'DRAW':
            return 'Bullish diesel/heating oil - long BNO; supportive of refiner margins'
        if regime == 'BUILD_HEAVY' or regime == 'BUILD':
            return 'Bearish distillate - soft industrial / freight demand'
        return 'Distillate range-bound'
    if category == 'refining':
        if regime == 'ELEVATED':
            return 'Refining utilisation high - peak crack-spread season; long XLE refiners (VLO, MPC)'
        if regime == 'DEPRESSED':
            return 'Refining utilisation low - turnaround season or demand weakness; cautious on refiners'
        return 'Refining at typical utilisation'
    if category == 'gasoline_demand':
        if regime == 'STRONG':
            return 'Strong gasoline demand - bullish UGA + refiners (VLO, MPC)'
        if regime == 'WEAK':
            return 'Weak gasoline demand - bearish UGA + refiners; defensive'
        return 'Demand at typical levels'
    return 'Monitor for regime shift'

rows = []
for si in range(len(SERIES)):
    ent = SERIES[si]
    sid = ent['id']
    desc = ent['desc']
    cat = ent['cat']
    etf = ent['etf']
    try:
        resp = requests.get(
            'https://api.eia.gov/v2/petroleum/stoc/wstk/data',
            params={
                'api_key': API_KEY,
                'frequency': 'weekly',
                'data[0]': 'value',
                'facets[series][]': sid,
                'sort[0][column]': 'period',
                'sort[0][direction]': 'desc',
                'offset': 0,
                'length': 270,
            },
            timeout=30,
        )
        resp.raise_for_status()
        payload = resp.json() or {}
        data_obj = payload.get('response', {}) or {}
        records = data_obj.get('data', []) or []
    except Exception:
        continue
    if not records:
        continue
    points = []
    unit = ''
    for ri in range(len(records)):
        rec = records[ri]
        if not isinstance(rec, dict):
            continue
        v = rec.get('value')
        if v is None:
            continue
        try:
            fv = float(v)
        except Exception:
            continue
        per = rec.get('period', '') or ''
        u = rec.get('units', '') or ''
        if u and not unit:
            unit = u
        points.append({'period': per, 'value': fv})
    if not points:
        continue
    latest = points[0]['value']
    period = points[0]['period']
    prior = points[1]['value'] if len(points) > 1 else None
    change_wow = None
    change_wow_pct = None
    if prior is not None:
        change_wow = round(latest - prior, 2)
        if prior != 0:
            change_wow_pct = round((latest - prior) / abs(prior) * 100.0, 2)
    idx_1y = 51 if 51 < len(points) else len(points) - 1
    v_1y = points[idx_1y]['value']
    change_yoy = None
    change_yoy_pct = None
    if v_1y is not None:
        change_yoy = round(latest - v_1y, 2)
        if v_1y != 0:
            change_yoy_pct = round((latest - v_1y) / abs(v_1y) * 100.0, 2)
    series_5y = []
    for vi in range(len(points)):
        if vi >= 260:
            break
        series_5y.append(points[vi]['value'])
    pct_5y = percentile(series_5y, latest)
    if cat == 'refining':
        regime = classify_refining(latest)
    elif cat == 'gasoline_demand':
        regime = classify_demand(change_yoy_pct)
    else:
        regime = classify_inventory(change_wow_pct)
    thesis = thesis_for(cat, regime, etf)
    rows.append({
        'series_id': sid,
        'description': desc,
        'category': cat,
        'unit': unit,
        'period': period,
        'latest_value': round(latest, 2),
        'prior_value': round(prior, 2) if prior is not None else None,
        'change_wow': change_wow,
        'change_wow_pct': change_wow_pct,
        'value_1y_ago': round(v_1y, 2) if v_1y is not None else None,
        'change_yoy': change_yoy,
        'change_yoy_pct': change_yoy_pct,
        'percentile_5y': pct_5y,
        'regime_flag': regime,
        'investment_thesis': thesis,
        'etf_ticker': etf,
        '_epoch': now_epoch,
    })

if rows:
    df = pd.DataFrame(rows, columns=EXPECTED_COLUMNS)
else:
    df = pd.DataFrame(columns=EXPECTED_COLUMNS)

